// Merge TikTok and Instagram scraped data
const tiktokData = $input.all().filter(i => i.json.platform === 'tiktok').map(i => i.json);
const instagramData = $input.all().filter(i => i.json.platform === 'instagram').map(i => i.json);

const tiktokItems = $node['Apify - TikTok Scraper']?.json?.items || [];
const instagramItems = $node['Apify - Instagram Scraper']?.json?.items || [];

// Extract hashtags from TikTok
const tiktokHashtags = {};
for (const item of tiktokItems) {
  if (item.hashtags) {
    for (const tag of item.hashtags) {
      const tagName = tag.name || tag;
      tiktokHashtags[tagName] = (tiktokHashtags[tagName] || 0) + 1;
    }
  }
}

// Sort by frequency
const sortedTiktokTags = Object.entries(tiktokHashtags)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 20)
  .map(([tag, count]) => ({ tag: `#${tag}`, count, platform: 'tiktok' }));

// Extract sounds from TikTok
const tiktokSounds = {};
for (const item of tiktokItems) {
  if (item.music?.title) {
    const soundKey = item.music.title;
    tiktokSounds[soundKey] = {
      name: item.music.title,
      author: item.music.authorName,
      count: (tiktokSounds[soundKey]?.count || 0) + 1
    };
  }
}

const sortedSounds = Object.values(tiktokSounds)
  .sort((a, b) => b.count - a.count)
  .slice(0, 10);

return [{
  json: {
    tiktokData: { hashtags: sortedTiktokTags, sounds: sortedSounds, rawItems: tiktokItems.slice(0, 10) },
    instagramData: { rawItems: instagramItems.slice(0, 10) },
    timestamp: new Date().toISOString(),
    niche: $json.body?.niche || null,
    tenantId: $json.body?.tenantId || null
  }
}];

const analysis = JSON.parse($input.first().json.message.content);
const rawData = $node['Merge & Process Scraped Data'].json;

return [{
  json: {
    analysis,
    rawData,
    tenantId: rawData.tenantId,
    niche: rawData.niche,
    timestamp: rawData.timestamp
  }
}];

